    rows += '<row r="' + r + '">';
    rows += '<c r="A' + r + '" s="6"><v>' + (idx + 1) + '</v></c>';
    rows += '<c r="B' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.regId) + '</t></is></c>';
    rows += '<c r="C' + r + '" s="8" t="inlineStr"><is><t>' + escapeXml(st.name) + '</t></is></c>';
    rows += '<c r="D' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.gender) + '</t></is></c>';
    rows += '<c r="E' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.contact) + '</t></is></c>';
    rows += '<c r="F' + r + '" s="8" t="inlineStr"><is><t>' + escapeXml(st.institute) + '</t></is></c>';
    rows += '<c r="G' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.course) + '</t></is></c>';
    rows += '<c r="H' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.semester) + '</t></is></c>';
    rows += '<c r="I' + r + '" s="6" t="inlineStr"><is><t>' + escapeXml(st.source) + '</t></is></c>';
