/**
 * Helper to build Sheet 3 (PARTICIPANT COUNT) XML
 */
function buildSheet3Xml(
  baseXml: string,
  exportDate: string,
  institutes: InstituteSummaryItem[],
  includeAju: boolean
): string {
  let rows = '';
  rows += '<row r="1" ht="56.25" customHeight="1"><c r="A1" s="1"/><c r="B1" s="2"/><c r="C1" s="3"/></row>';
  rows += '<row r="2" ht="38.25" customHeight="1"><c r="A2" s="1"/><c r="B2" s="2"/><c r="C2" s="3"/></row>';
  rows += '<row r="3"><c r="A3" s="4" t="inlineStr"><is><t>EXPORT DATE : ' + escapeXml(exportDate) + '</t></is></c><c r="B3" s="2"/><c r="C3" s="3"/></row>';
  rows += '<row r="4"><c r="A4" s="6" t="inlineStr"><is><t>S No.</t></is></c><c r="B4" s="6" t="inlineStr"><is><t>INSTITUTE NAME</t></is></c><c r="C4" s="6" t="inlineStr"><is><t>PARTICIPANT COUNT</t></is></c></row>';

  institutes.forEach((inst, idx) => {
    const r = idx + 5;
    rows += '<row r="' + r + '"><c r="A' + r + '" s="6"><v>' + (idx + 1) + '</v></c><c r="B' + r + '" s="8" t="inlineStr"><is><t>' + escapeXml(inst.name) + '</t></is></c><c r="C' + r + '" s="6"><v>' + inst.count + '</v></c></row>';
  });

  const totalRow = institutes.length + 5;
  const totalCount = institutes.reduce((s, i) => s + i.count, 0);
  rows += '<row r="' + totalRow + '"><c r="A' + totalRow + '" s="6" t="inlineStr"><is><t>TOTAL</t></is></c><c r="B' + totalRow + '" s="6" t="inlineStr"><is><t>' + institutes.length + ' INSTITUTIONS ' + (includeAju ? '(ALL)' : '(EXTERNAL ONLY)') + '</t></is></c><c r="C' + totalRow + '" s="6"><v>' + totalCount + '</v></c></row>';

  return replaceSheetData(baseXml, rows);
}

/**
 * Configure active tab in workbook.xml
 * sheet 0: Institute Wise Data
 * sheet 1: Event Wise Data
 * sheet 2: PARTICIPANT COUNT
 */
function setActiveTab(wbXml: string, activeIndex: number): string {
  if (wbXml.includes('<bookViews>')) {
    return wbXml.replace(/<workbookView [^>]*\/>/, '<workbookView activeTab="' + activeIndex + '"/>');
  }
  return wbXml.replace('<workbookPr/>', '<workbookPr/><bookViews><workbookView activeTab="' + activeIndex + '"/></bookViews>');
}

/**
 * Generate Master XLSX with all 3 sheets populated!
 */
export async function generateMasterXlsxBlob(options: {
  exportDate: string;
  institutes: InstituteSummaryItem[];
  includeAju: boolean;
  instituteParticipants: InstituteParticipantItem[];
  selectedInstituteName: string;
  eventParticipants: EventParticipantItem[];
  selectedEventName: string;
  activeSheetIndex?: number; // 0: Institute, 1: Event, 2: Participant Count
}): Promise<Blob> {
  const zip = await JSZip.loadAsync(BASE_XLSX_TEMPLATE_B64, { base64: true });

  // 1. Sheet 1: Institute Wise Data
  const s1 = await zip.file('xl/worksheets/sheet1.xml')!.async('string');
  const newS1 = buildSheet1Xml(s1, options.selectedInstituteName, options.exportDate, options.instituteParticipants);
  zip.file('xl/worksheets/sheet1.xml', newS1);

  // 2. Sheet 2: Event Wise Data
  const s2 = await zip.file('xl/worksheets/sheet2.xml')!.async('string');
  const newS2 = buildSheet2Xml(s2, options.selectedEventName, options.exportDate, options.eventParticipants);
  zip.file('xl/worksheets/sheet2.xml', newS2);

  // 3. Sheet 3: PARTICIPANT COUNT
  const s3 = await zip.file('xl/worksheets/sheet3.xml')!.async('string');
  const newS3 = buildSheet3Xml(s3, options.exportDate, options.institutes, options.includeAju);
  zip.file('xl/worksheets/sheet3.xml', newS3);

  // 4. Set Active Tab
  if (options.activeSheetIndex !== undefined) {
    const wb = await zip.file('xl/workbook.xml')!.async('string');
    zip.file('xl/workbook.xml', setActiveTab(wb, options.activeSheetIndex));
  }

  return await zip.generateAsync({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    compression: 'DEFLATE'
  });
}
